// ---------------------------------------------------------------------------
// Stripe replay dispatcher
// Delegates to processStripeEvent — the single source of truth for Stripe
// event dispatch. Adding a new event type only requires a change in
// lib/payments/process-stripe-event.ts; the replay path picks it up automatically.
//
// Casting the worker supabase client is safe: both @supabase/supabase-js
// createClient and @supabase/ssr createServerClient are structurally identical
// for the RPC + from operations used inside processStripeEvent. The type cast
// bridges the nominal difference without runtime risk.
// ---------------------------------------------------------------------------

async function replayStripeEvent(
  rawPayload: unknown,
  eventType: string,
  jobLog: Logger,
): Promise<void> {
  jobLog.info({ eventType }, 'webhook-replay: dispatching stripe event via processStripeEvent')

  // Reconstruct Stripe.Event from the stored payload JSON — the original event
  // object was stored verbatim in webhook_events.payload at ingest time.
  const event = rawPayload as Stripe.Event

  // The worker's supabase client is structurally identical to SupabaseServiceClient
  // for all operations processStripeEvent performs (rpc + from). Cast bridges the
  // nominal type gap between @supabase/supabase-js and @supabase/ssr client types.
  type SupabaseServiceClient = Parameters<typeof processStripeEvent>[1]
  await processStripeEvent(event, supabase as unknown as SupabaseServiceClient)
}

